// ── Users & roles ────────────────────────────────────────────────────────────
// Each user is { id, name, department, pinSalt, pinHash, authVersion } stored as
// one JSON array in the
// USERS Script Property. `id` is the durable identity a session token binds
// to — name and PIN are both editable from the in-app User Management
// screen, so auth and attribution can't depend on either staying fixed.
// The live roster stays in Script Properties. Temporary PINs are generated by
// position rather than stored as plaintext constants in source.
const TOKEN_TTL_MS = 12 * 3600 * 1000; // one workday; shared devices should not stay signed in for weeks
const TV_TOKEN_TTL_MS = 365 * 24 * 3600 * 1000; // dedicated read-only display; Admin can revoke it at any time
const TOKEN_HANDOFF_GRACE_MS = 30 * 1000; // lets an in-flight request finish while My Account stores its replacement token
const TRAINING_PIN_BATCH = '2026-08-07-six-digit';
const PIN_CHANGE_STATUS_BATCH = '2026-08-10-required-pin-change';
const MAX_ADDITIONAL_FILE_BYTES = 8 * 1024 * 1024;
const MAX_ADDITIONAL_FILES_PER_JOB = 50;
const MAX_STANDARD_REQUEST_CHARS = 250000;
const MAX_UPLOAD_REQUEST_CHARS = 12 * 1024 * 1024;

const DEPARTMENTS = ['Admin', 'Manager', 'Viewer', 'Costing Viewer', 'TV', 'Manufacturing', 'Graphics', 'Routing', 'Paint', 'Letters', 'Assembly'];

// Job-assignable tags — distinct from the user DEPARTMENTS list above.
// Ship-In isn't a role anyone logs in as; it's a job-only tag meaning "made
// elsewhere, just shipped in to us" rather than produced in one of our shops.
const JOB_DEPARTMENTS = ['Manufacturing', 'Graphics', 'Routing', 'Paint', 'Letters', 'Assembly'];
const JOB_TAGS = JOB_DEPARTMENTS.concat(['Ship-In']);

function canAssignDepartments(department) {
  return department === 'Admin' || department === 'Manager';
}

function canUseJobSelector(department) {
  return JOB_DEPARTMENTS.indexOf(String(department || '')) !== -1;
}

function canViewJobTimeLog(actor) {
  if (!actor) return false;
  return ['Admin', 'Manager', 'Viewer', 'Costing Viewer'].indexOf(actor.department) !== -1;
}

function canEditJobTimeLog(actor) {
  if (!actor) return false;
  return actor.department === 'Admin' || actor.department === 'Costing Viewer';
}

function canManageCostingButtons(department) {
  return department === 'Admin' || department === 'Costing Viewer';
}

function canUploadAdditionalFiles(department) {
  return department === 'Admin' || department === 'Manager' || department === 'Viewer' || department === 'Costing Viewer';
}

function additionalFilesForClient(files) {
  return (files || []).map(file => {
    const { fileId, ...visible } = file;
    return visible;
  });
}

// Only Admin/Manager can mark an entire job complete. Production-department
// accounts complete their own tasks (see toggleDepartmentTaskDone), not the
// whole job; Viewers never complete anything.
function canMarkJobComplete(department) {
  return department === 'Admin' || department === 'Manager';
}

// Who may manually override a job's calculated due date, for one-off
// scheduling edge cases the automatic 2-business-day rule gets wrong.
//
// This used to be a list of NAMES (`DUE_DATE_EDITORS = ['Jake Banks']`)
// compared against actor.name — which was a privilege escalation, because
// updateSelf() lets any signed-in account (including a Viewer) rename itself
// to anything with no uniqueness check. Renaming yourself to a listed name
// granted you the permission. Permissions must key off something the holder
// can't edit: department here, exactly like canAssignDepartments and
// canMarkJobComplete above. Names are display data, never authorization.
function canEditDueDates(department) {
  return department === 'Admin';
}

// The Project Handoff queue is a management/read-only surface. Managers may
// schedule these otherwise-unscheduled production jobs, but that narrower
// permission does not grant them due-date access on install-calendar jobs.
function canViewOtherProduction(department) {
  return department === 'Admin' || department === 'Manager' || department === 'Viewer';
}

function canEditDueDateForJob(department, job) {
  return canEditDueDates(department)
    || (department === 'Manager' && !!(job && job.isOtherProduction));
}

// Departments a Manager can't see in the user list at all.
const PM_HIDDEN_DEPARTMENTS = ['Admin', 'Viewer', 'Costing Viewer', 'TV'];
// Departments a Manager can see but can't add/edit/delete — separate from
// PM_HIDDEN_DEPARTMENTS because a Manager *can* see fellow Managers, just
// not manage them.
const PM_BLOCKED_EDIT_DEPARTMENTS = ['Admin', 'Manager', 'Viewer', 'Costing Viewer', 'TV'];

function canAccessUserManagement(department) {
  return department === 'Admin' || department === 'Manager';
}

// Whether a user in `actorDepartment` may add/edit/delete a user in
// `targetDepartment`. Admins can manage everyone; Managers can manage
// everyone except Admin/Manager/Viewer accounts; everyone else has no
// user-management access at all.
function canManageDepartment(actorDepartment, targetDepartment) {
  if (actorDepartment === 'Admin') return true;
  if (actorDepartment === 'Manager') return PM_BLOCKED_EDIT_DEPARTMENTS.indexOf(targetDepartment) === -1;
  return false;
}

function isLastAdmin(users, userId) {
  const admins = users.filter(u => u.department === 'Admin');
  return admins.length === 1 && admins[0].id === userId;
}

function visibleUsersFor(actor) {
  const users = getUsers();
  const visible = actor.department === 'Admin'
    ? users
    : users.filter(u => PM_HIDDEN_DEPARTMENTS.indexOf(u.department) === -1);
  return visible.map(user => userFor(actor, user));
}

function userFor(actor, user) {
  const visible = publicUser(user);
  if (actor.department === 'Admin' && user.adminPin) visible.pin = user.adminPin;
  return visible;
}

// Placeholder only, mirroring the old DEFAULT_PINS pattern — real users
// come from migrateLegacyPins() (see getUsers()) or get added through the
// in-app User Management screen. Never paste real PINs here.
function defaultUsers() {
  return [withNewPin({ id: Utilities.getUuid(), name: 'Replace Me', department: 'Admin', authVersion: 1 }, '000000')];
}

// One-time upgrade path from the old flat PINS { pin: name } map: Jake
// Banks becomes the sole Admin, everyone else comes in as a Viewer,
// preserving whatever PINs are already live. Runs automatically the first
// time getUsers() finds no USERS property yet, so no manual step is needed.
function migrateLegacyPins() {
  const raw = PropertiesService.getScriptProperties().getProperty('PINS');
  if (!raw) return null;
  let legacy;
  try { legacy = JSON.parse(raw); } catch (err) { return null; }
  return Object.keys(legacy).map(pin => ({
    id: Utilities.getUuid(),
    name: legacy[pin],
    department: legacy[pin] === 'Jake Banks' ? 'Admin' : 'Viewer',
    pin: String(pin),
  }));
}

function getUsers() {
  const props = PropertiesService.getScriptProperties();
  const raw = props.getProperty('USERS');
  if (raw) {
    const users = JSON.parse(raw);
    const changed = renameLegacyManagerLabel(users) | migrateUserCredentials(users);
    const trainingPinsApplied = applyTemporaryTrainingPins(users, props);
    const pinStatusApplied = markTemporaryPinStatus(users, props);
    if (changed || trainingPinsApplied || pinStatusApplied) saveUsers(users);
    if (trainingPinsApplied) props.setProperty('TRAINING_PIN_BATCH', TRAINING_PIN_BATCH);
    if (pinStatusApplied) props.setProperty('PIN_CHANGE_STATUS_BATCH', PIN_CHANGE_STATUS_BATCH);
    return users;
  }
  const users = migrateLegacyPins() || defaultUsers();
  migrateUserCredentials(users);
  const trainingPinsApplied = applyTemporaryTrainingPins(users, props);
  const pinStatusApplied = markTemporaryPinStatus(users, props);
  saveUsers(users);
  if (trainingPinsApplied) props.setProperty('TRAINING_PIN_BATCH', TRAINING_PIN_BATCH);
  if (pinStatusApplied) props.setProperty('PIN_CHANGE_STATUS_BATCH', PIN_CHANGE_STATUS_BATCH);
  return users;
}

// One-time training reset requested before launch. Every account gets a unique
// six-digit PIN based on its alphabetical position, and existing sessions are
// invalidated. Lionel starts as Viewer so an Admin can assign his department
// without accidentally granting production or management access.
function applyTemporaryTrainingPins(users, props) {
  if (props.getProperty('TRAINING_PIN_BATCH') === TRAINING_PIN_BATCH) return false;
  if (!users.some(user => user.name.toLowerCase() === 'lionel gonzalez')) {
    users.push({ id: Utilities.getUuid(), name: 'Lionel Gonzalez', department: 'Viewer', authVersion: 1 });
  }
  users.sort((a, b) => a.name.localeCompare(b.name));
  users.forEach((user, index) => {
    Object.assign(user, withNewPin(user, String(index + 1).padStart(6, '0')));
    user.authVersion = (+user.authVersion || 1) + 1;
    user.mustChangePin = true;
    delete user.pinRecoveryAttempted;
  });
  return true;
}

// Accounts that still have the predictable alphabetical training PIN are
// required to replace it. Users who already changed their PIN before this
// release are detected from the current Admin-visible copy and left alone.
function markTemporaryPinStatus(users, props) {
  if (props.getProperty('PIN_CHANGE_STATUS_BATCH') === PIN_CHANGE_STATUS_BATCH) return false;
  const sorted = users.slice().sort((a, b) => a.name.localeCompare(b.name));
  sorted.forEach((user, index) => {
    const trainingPin = String(index + 1).padStart(6, '0');
    user.mustChangePin = user.adminPin === trainingPin;
  });
  return true;
}

// One-time rename: the "Production Manager" department became "Manager".
// Mutates in place and reports whether anything changed, so getUsers() only
// re-saves when there's actually a legacy value to fix — after the first
// read post-deploy this is a no-op.
function renameLegacyManagerLabel(users) {
  let changed = false;
  users.forEach(u => {
    if (u.department === 'Production Manager') { u.department = 'Manager'; changed = true; }
  });
  return changed;
}

function saveUsers(users) {
  users.forEach(user => { delete user.pin; });
  PropertiesService.getScriptProperties().setProperty('USERS', JSON.stringify(users));
}

function hashPin(pin, salt) {
  const bytes = Utilities.computeHmacSha256Signature(String(pin), getAuthSecret() + ':' + salt);
  return Utilities.base64EncodeWebSafe(bytes);
}

function withNewPin(user, pin) {
  const next = { ...user, pinSalt: Utilities.getUuid(), adminPin: String(pin) };
  next.pinHash = hashPin(pin, next.pinSalt);
  delete next.pin;
  return next;
}

// Transparently upgrades old plaintext USERS records before the one-time
// six-digit training reset replaces every credential.
function migrateUserCredentials(users) {
  let changed = false;
  users.forEach(user => {
    if (!user.authVersion) { user.authVersion = 1; changed = true; }
    if (user.pin !== undefined) {
      const secured = withNewPin(user, String(user.pin));
      user.pinSalt = secured.pinSalt;
      user.pinHash = secured.pinHash;
      user.adminPin = secured.adminPin;
      delete user.pin;
      changed = true;
    }
  });
  return changed;
}

function pinMatches(user, pin) {
  return !!(user && user.pinSalt && user.pinHash && hashPin(pin, user.pinSalt) === user.pinHash);
}

function pinAlreadyUsed(users, pin, exceptId) {
  return users.some(user => user.id !== exceptId && pinMatches(user, pin));
}
